// SQLite persistence: opens (creating if needed) data/bookmarks.db and runs an
// idempotent schema migration. Single-user app, so no per-user tables.
import Database from 'better-sqlite3';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { mkdirSync } from 'node:fs';

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_DIR = join(__dirname, '..', 'data');
const SNAPSHOT_DIR = join(DATA_DIR, 'snapshots');

mkdirSync(SNAPSHOT_DIR, { recursive: true });

const db = new Database(join(DATA_DIR, 'bookmarks.db'));
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

db.exec(`
  CREATE TABLE IF NOT EXISTS bookmarks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    url TEXT NOT NULL,
    normalized_url TEXT NOT NULL UNIQUE,
    title TEXT NOT NULL DEFAULT '',
    description TEXT NOT NULL DEFAULT '',
    notes_html TEXT NOT NULL DEFAULT '',
    favicon_url TEXT,
    preview_image_url TEXT,
    is_read INTEGER NOT NULL DEFAULT 0,
    is_archived INTEGER NOT NULL DEFAULT 0,
    saved_date INTEGER NOT NULL,
    updated_date INTEGER NOT NULL,
    offline_status TEXT NOT NULL DEFAULT 'pending',
    offline_kind TEXT,
    offline_path TEXT,
    ia_status TEXT NOT NULL DEFAULT 'none',
    ia_snapshot_url TEXT
  );

  CREATE TABLE IF NOT EXISTS tags (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL COLLATE NOCASE UNIQUE
  );

  CREATE TABLE IF NOT EXISTS bookmark_tags (
    bookmark_id INTEGER NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE,
    tag_id INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
    PRIMARY KEY (bookmark_id, tag_id)
  );

  CREATE TABLE IF NOT EXISTS saved_filters (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    query TEXT NOT NULL DEFAULT '',
    include_tags TEXT NOT NULL DEFAULT '[]',
    exclude_tags TEXT NOT NULL DEFAULT '[]',
    created_date INTEGER NOT NULL
  );

  CREATE TABLE IF NOT EXISTS preferences (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    default_sort TEXT NOT NULL DEFAULT 'date_added_desc',
    density TEXT NOT NULL DEFAULT 'comfortable',
    text_size TEXT NOT NULL DEFAULT 'medium'
  );

  INSERT OR IGNORE INTO preferences (id) VALUES (1);

