  CREATE INDEX IF NOT EXISTS idx_bookmarks_saved ON bookmarks(saved_date);
  CREATE INDEX IF NOT EXISTS idx_bookmarks_title ON bookmarks(title);
`);

export { db, DATA_DIR, SNAPSHOT_DIR };

