:root {
  --bg: #f6f7f9;
  --panel: #ffffff;
  --ink: #1c2330;
  --muted: #667085;
  --line: #e3e7ee;
  --accent: #2f6feb;
  --danger: #d64545;
  --radius: 10px;
  --fs: 15px;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  color: var(--ink);
  background: var(--bg);
  font-size: var(--fs);
}
body[data-text-size="small"] { --fs: 13px; }
body[data-text-size="medium"] { --fs: 15px; }
body[data-text-size="large"] { --fs: 18px; }

h1 { font-size: 1.25rem; margin: 0; }
h2 { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); margin: 0 0 0.5rem; }

button, .topbar-actions a {
  font: inherit;
  cursor: pointer;
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--ink);
  border-radius: 8px;
  padding: 0.4rem 0.7rem;
  text-decoration: none;
}
button:hover { border-color: var(--accent); }
button.danger, button.danger:hover { color: var(--danger); border-color: var(--danger); }
.link-btn { border: none; background: none; color: var(--accent); padding: 0.2rem 0; }

.topbar {
  display: flex; align-items: center; gap: 1rem;
  padding: 0.75rem 1.25rem; background: var(--panel); border-bottom: 1px solid var(--line);
  position: sticky; top: 0; z-index: 5; flex-wrap: wrap;
}
.add-form { display: flex; gap: 0.4rem; flex: 1; min-width: 260px; }
.add-form input { flex: 1; }
.topbar-actions { display: flex; gap: 0.4rem; }

input[type="text"], input[type="search"], select, textarea, input[type="file"] {
  font: inherit; padding: 0.45rem 0.6rem; border: 1px solid var(--line);
  border-radius: 8px; background: #fff; color: var(--ink);
}
input:focus, select:focus, button:focus, [contenteditable]:focus { outline: 2px solid var(--accent); outline-offset: 1px; }

.layout { display: flex; align-items: flex-start; gap: 1.25rem; padding: 1.25rem; max-width: 1200px; margin: 0 auto; }
.sidebar { width: 220px; flex-shrink: 0; display: flex; flex-direction: column; gap: 1.25rem; }
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 0.9rem; }
.views { display: flex; flex-direction: column; gap: 0.3rem; }
.view-tab { text-align: left; }
.view-tab.active { background: var(--accent); color: #fff; border-color: var(--accent); }

.tag-list, .filter-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.2rem; }
.tag-list li, .filter-list li { display: flex; justify-content: space-between; align-items: center; gap: 0.4rem; }
.tag-list button { border: none; background: none; padding: 0.2rem 0; text-align: left; flex: 1; }
.tag-list .count { color: var(--muted); font-size: 0.8em; }
.filter-list .apply { border: none; background: none; text-align: left; flex: 1; color: var(--accent); }
.filter-list .del { border: none; background: none; color: var(--muted); }

.content { flex: 1; min-width: 0; }
.toolbar { display: flex; gap: 0.75rem; margin-bottom: 0.75rem; align-items: center; }
.toolbar #search { flex: 1; }
.sort { color: var(--muted); font-size: 0.85rem; display: flex; align-items: center; gap: 0.35rem; }

.active-filter { background: #eaf1ff; border: 1px solid #cfe0ff; color: #234; padding: 0.4rem 0.7rem; border-radius: 8px; margin-bottom: 0.6rem; display: flex; justify-content: space-between; }
.active-filter button { border: none; background: none; color: var(--accent); }

.bulk-bar { display: flex; align-items: center; gap: 0.5rem; background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 0.5rem 0.75rem; margin-bottom: 0.6rem; flex-wrap: wrap; }
.bulk-bar .spacer { flex: 1; }

.bookmark-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.6rem; }
.card {
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 0.8rem; display: grid; grid-template-columns: auto 32px 1fr auto; gap: 0.7rem; align-items: start;
}
.card .sel { margin-top: 0.2rem; }
.card .favicon { width: 32px; height: 32px; border-radius: 6px; background: #eef1f6; object-fit: contain; }
.card .body { min-width: 0; }
.card .title { font-weight: 600; color: var(--ink); text-decoration: none; font-size: 1.02em; }
.card .title:hover { color: var(--accent); text-decoration: underline; }
.card .url { color: var(--muted); font-size: 0.82em; display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.card .desc { margin: 0.3rem 0 0; color: #384150; }
.card .chips { display: flex; flex-wrap: wrap; gap: 0.3rem; margin-top: 0.4rem; }
.chip { background: #eef1f6; border-radius: 999px; padding: 0.1rem 0.55rem; font-size: 0.78em; color: #3a4a63; cursor: pointer; border: none; }
.chip:hover { background: #dde6f5; }
.card .meta { display: flex; flex-direction: column; align-items: flex-end; gap: 0.3rem; font-size: 0.8em; }
.card .actions { display: flex; gap: 0.25rem; flex-wrap: wrap; justify-content: flex-end; }
.card .actions button { padding: 0.2rem 0.45rem; font-size: 0.85em; }
.badge { font-size: 0.72em; padding: 0.1rem 0.4rem; border-radius: 6px; }
.badge.unread { background: #fff3d6; color: #8a6100; }
.badge.offline-available { background: #e0f3e4; color: #1c6b34; }
.badge.offline-unavailable { background: #f5e1e1; color: #97363a; }
.badge.offline-pending { background: #eceef2; color: var(--muted); }
.badge.ia-saved { background: #e5eefc; color: #22508f; }

/* Compact density hides descriptions and shrinks padding */
body[data-density="compact"] .card { padding: 0.5rem 0.7rem; gap: 0.5rem; }
body[data-density="compact"] .card .desc { display: none; }

.empty-state { text-align: center; color: var(--muted); padding: 3rem 1rem; background: var(--panel); border: 1px dashed var(--line); border-radius: var(--radius); }

/* Modals */
.modal-root { position: fixed; inset: 0; background: rgba(20,28,40,0.45); display: flex; align-items: center; justify-content: center; padding: 1rem; z-index: 20; }
.modal { background: var(--panel); border-radius: 12px; width: min(560px, 100%); max-height: 90vh; overflow: auto; padding: 1.25rem; }
.modal h3 { margin-top: 0; }
.modal label { display: block; margin: 0.6rem 0 0.2rem; font-size: 0.85rem; color: var(--muted); }
.modal input[type="text"], .modal textarea, .modal select { width: 100%; }
.modal .row { display: flex; gap: 0.5rem; justify-content: flex-end; margin-top: 1rem; }
.modal .preview-thumb { max-width: 100%; max-height: 160px; border-radius: 8px; border: 1px solid var(--line); margin-top: 0.3rem; }
.suggest { position: relative; }
.suggest-list { list-style: none; margin: 0.2rem 0 0; padding: 0; border: 1px solid var(--line); border-radius: 8px; background: #fff; position: absolute; width: 100%; z-index: 3; max-height: 160px; overflow: auto; }
.suggest-list li { padding: 0.35rem 0.6rem; cursor: pointer; }
.suggest-list li:hover, .suggest-list li.active { background: #eef3ff; }
.tag-input-chips { display: flex; flex-wrap: wrap; gap: 0.3rem; margin-top: 0.3rem; }
.tag-input-chips .chip { cursor: default; }
.tag-input-chips .chip button { border: none; background: none; color: var(--muted); padding: 0 0 0 0.2rem; cursor: pointer; }
.notes-toolbar { display: flex; gap: 0.3rem; margin-bottom: 0.3rem; }
.notes-toolbar button { padding: 0.2rem 0.5rem; font-weight: 600; }
.notes-editor { min-height: 120px; border: 1px solid var(--line); border-radius: 8px; padding: 0.6rem; background: #fff; }
.notes-editor:empty::before { content: attr(data-placeholder); color: var(--muted); }
.notes-view { border: 1px solid var(--line); border-radius: 8px; padding: 0.6rem; background: #fbfcfe; }
.fallback-note { color: #8a6100; font-size: 0.82rem; margin-top: 0.3rem; }
.hint { color: var(--muted); font-size: 0.82rem; }

@media (max-width: 800px) {
  .layout { flex-direction: column; }
  .sidebar { width: 100%; flex-direction: row; flex-wrap: wrap; }
  .sidebar .panel, .sidebar .views { flex: 1; min-width: 160px; }
}

